<template>
  <div class="admin-page">
    <Header title="Biblioteca de Trabalhos Acadêmicos" :hideToggle="false"/>
    <Menu />
    <div id="usuarioList-content">
      <PageTitle icon="fa fa-home" main="Usuário" sub="Listagem"/>
      <b-table hover striped :items="usuarios" :fields="fields">
        <template slot="actions" slot-scope="row">
          <b-button variante="primary" class="mr-2">
            <i class="fa fa-pencil"></i>
          </b-button>
          <b-button variante="danger" @click="modal(row.item)">
            <i class="fa fa-trash"></i>
          </b-button>
        </template>
      </b-table>
    </div>
    <Footer />

    <div v-if="showModalEdit">
        <transition name="modal">
          <div class="modal-mask">
            <div class="modal-wrapper">
              <div class="modal-dialog" role="document">
                <div class="modal-content">
                  <div class="modal-header">
                    <h5 class="modal-title">Excluir</h5>
                    <button type="button" class="close" data-dismiss="modal" aria-label="Close">
                      <span aria-hidden="true" @click="showModalEdit = false">&times;</span>
                    </button>
                  </div>
                  <div class="modal-body">
                    <p>Deseja excluir o Usuário {{ usuarioEscolhido }}?</p>
                  </div>
                  <div class="modal-footer">
                    <button type="button" class="btn btn-primary" @click="showModalEdit = false">Cancelar</button>
                    <button type="button" class="btn btn-danger" @click="excluir" >Excluir</button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </transition>
      </div>

  </div>
</template>

<script>
import { showError } from '../../../config/global'
import { mapState } from 'vuex'
import axios from 'axios'
import PageTitle from '../templates/PageTitle'
import Header from '../templates/Header'
import Menu from '../templates/Menu'
import Footer from '../templates/Footer'

export default {
    name: 'UsuarioList',
    components: { PageTitle, Header, Menu, Footer },
    computed: mapState(['isMenuVisible']),
    data: function(){
      return{
        showModalEdit: false,
        usuarioEscolhido: '',
        usuarios: [],
        fields: [
          {key: 'id', label: 'Código', sortable: false},
          {key: 'name', label: 'Nome', sortable: true},
          {key: 'email', label: 'E-mail', sortable: false},
          {key: 'admin', label: 'Administrador', sortable: true, formatter: value => value ? 'Sim' : 'Não'},
          {key: 'actions', label: 'Ações'}
        ]
      }
    },
    mounted(){
      axios.get('https://api.myjson.com/bins/se0zw')
          .then(response => (this.usuarios = response.data))
          .catch(showError)

      document.title = "BTA - Lista de Usuários"
    },
    methods: {
      excluir(){
        alert('Deletado')
        this.showModalEdit = false
      },
      modal(item){
        this.usuarioEscolhido = item.name
        this.showModalEdit = true
      }
    }
}
</script>

<style>
  #usuarioList-content{
    grid-area: contentAdmin;
    background-color: #efefef;
    padding: 20px;
  }
</style>