<template>
  <div class="admin-page">
    <Header title="Biblioteca de Trabalhos Acadêmicos" :hideToggle="false"/>
    <Menu />
    <div id="projetoAdd-content">
      <PageTitle icon="fa fa-home" main="Projeto" sub="Cadastro"/>
      <b-form>
        <b-row>
          <b-col md="6" sm="12">
              <b-form-group label="Título do Projeto:" label-for="projeto-titulo">
                  <b-form-input id="projeto-name" type="text" v-model="projeto.name" placeholder="Digite o Título do Projeto" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
          <b-col md="6" sm="12">
              <b-form-group label="Subtítulo do Projeto:" label-for="projeto-subtitulo">
                  <b-form-input id="projeto-subtitulo" type="text" v-model="projeto.subTitulo" placeholder="Digite o Subtítulo do Projeto" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
        </b-row>
        <b-row>
          <b-col md="6" sm="12">
              <b-form-group label="Orientador:" label-for="projeto-orientador">
                <b-form-select
                  id="projeto-orientador"
                  v-model="projeto.orientador"
                  :options="orientadores"
                  required
                ></b-form-select>
              </b-form-group>
          </b-col>
          <b-col md="6" sm="12">
              <b-form-group label="Curso:" label-for="projeto-curso">
                <b-form-select
                  id="projeto-curso"
                  v-model="projeto.curso"
                  :options="cursos"
                  required
                ></b-form-select>
              </b-form-group>
          </b-col>
        </b-row>
        <div>
          <b-row v-for="i in contAluno" :key="i">
            <b-col md="6" sm="12">
                <b-form-group :label="'Nome do Aluno ' + i + ':'" label-for="projeto-aluno-nome">
                    <b-form-input id="projeto-aluno-nome" type="text" v-model="projeto.nome" :placeholder="'Digite o Nome do Aluno ' + i" required>
                    </b-form-input>
                </b-form-group>
            </b-col>
            <b-col md="6" sm="12">
                <b-form-group :label="'RA do Aluno ' + i + ':'" label-for="projeto-aluno-ra">
                    <b-form-input id="projeto-aluno-ra" type="text" v-model="projeto.ra" :placeholder="'Digite o RA do Aluno ' + i" required>
                    </b-form-input>
                </b-form-group>
            </b-col>
          </b-row>
          <b-button @click="adicionarCont(1)" class="mb-3 mr-2">
            Adicionar Aluno
          </b-button>
          <b-button variant="danger" @click="removerCont(1)" class="mb-3">
            Remover Aluno
          </b-button>
        </div>
        <div>
          <b-row>
            <b-col md="3" sm="6" v-for="i in contPalavras" :key="i" >
                <b-form-group :label="'Palavra-Chave ' + i + ':'" label-for="projeto-aluno">
                    <b-form-input id="projeto-palavra" type="text" v-model="projeto.palavras" :placeholder="'Digite a Palavra-Chave ' + i" required>
                    </b-form-input>
                </b-form-group>
            </b-col>
          </b-row>
          <b-button @click="adicionarCont(2)" class="mb-3 mr-2">
            Adicionar Palavra-Chave
          </b-button>
          <b-button variant="danger" @click="removerCont(2)" class="mb-3">
            Remover Palavra-Chave
          </b-button>
        </div>
        <b-row>
          <b-col md="12" sm="12">
            <b-form-group label="Resumo do Projeto" label-for="projeto-aluno">
              <b-form-textarea
                id="projeto-resumo"
                v-model="text"
                placeholder="Resumo do Projeto..."
                rows="3"
                max-rows="6"
              ></b-form-textarea>
            </b-form-group>
          </b-col>
        </b-row>
        <b-row>
          <b-col md="12">
            <b-form-group label="Arquivo do Projeto" label-for="projeto-aluno">
              <b-form-file
                accept=".pdf"
                v-model="projeto.file"
                :state="Boolean(file)"
                placeholder="Escolha um arquivo PDF ou coloque-o aqui"
                drop-placeholder="Pesquisar"
              ></b-form-file>
            </b-form-group>
          </b-col>
        </b-row>
        <b-button variant="primary" @click='save'>
          Salvar
        </b-button>
        <b-button class="ml-2" @click='reset'>
          Cancelar
        </b-button>
      </b-form>
    </div>
    <Footer />
  </div>
</template>

<script>
import { baseUrl, showError } from '../../../config/global'
import { mapState } from 'vuex'
import axios from 'axios'
import PageTitle from '../templates/PageTitle'
import Header from '../templates/Header'
import Menu from '../templates/Menu'
import Footer from '../templates/Footer'

export default {
    name: 'UsuarioList',
    components: { PageTitle, Header, Menu, Footer },
    computed: mapState(['isMenuVisible']),
    data: function(){
      return{
        projeto:{
          tituloProjeto: '',
          subTitulo: '',
          aluno: [],
          ra: [],
          curso: '',
          orientador: '',
          palavras: [],
          resumo: '',
          file: null
        },
        orientadores: ['Silvia Farani', 'Magali Rossi', 'Andreia Machion'],
        cursos: ['Análise e Desenvolvimento de Sistemas', 'Logística', 'Secretariado'],
        contAluno: 1,
        contPalavras: 1
      }
    },
    methods:{
      removerCont(x){
        if(this.contAluno > 1 && x == 1)
          return this.contAluno--
        if(this.contPalavras > 1 && x == 2)
          return this.contPalavras--
      },
      adicionarCont(x){
        if(this.contAluno != 5 && x == 1)
          return this.contAluno++
        if(this.contPalavras != 5 && x == 2)
          return this.contPalavras++
      },
      reset(){
        this.projeto = {}
      },
      save(){
        axios.post(`${baseUrl}`)
          .then(() => {
            this.$toasted.global.defaultSuccess()
          })
          .catch(showError())
      }
    },
    mounted(){
      document.title = "BTA - Adicionar Projeto"
    }
}
</script>

<style>
  #projetoAdd-content{
    grid-area: contentAdmin;
    background-color: #efefef;
    padding: 20px;
  }

  .custom-file-input:lang(en) ~ .custom-file-label::after {
    content: "Buscar";
  }
</style>