<template>
    <div class="page">
        <!-- HEADER -->
        <Header />

        <main class="container main">
            <h2 class="tituloPagina">Ranking</h2>
                <b-table 
                    class="table-rank"
                    striped hover 
                    :items="projetos" 
                    :fields="fields"
                    :sort-by.sync="sortBy"
                    :sort-desc.sync="sortDesc"
                    :per-page="perPage"
                    :current-page="currentPage"
                >
                    <template slot="tituloProjeto" slot-scope="titulo">
                        <a href="#" target="_blank"> {{ titulo.item.tituloProjeto }} </a>
                    </template>
                    <template slot="autores" slot-scope="aluno">
                        {{ aluno.item.autores|formatarAlunos }}
                    </template>
                    <template slot="dataAvaliacao" slot-scope="dataAvaliacao">
                        {{ dataAvaliacao.item.dataAvaliacao|formatarAno }}
                    </template>
                    <template slot="download" slot-scope="downloadItem">
                        <b-button variante="primary" class="ml-3">
                            <a class="download" :href="baseUrl + '/projetos/download_file/' + downloadItem.item.nomeArquivo" download=""><i class="fa fa-download"></i></a>
                        </b-button>
                    </template>
                </b-table>
                <b-pagination
                    v-model="currentPage"
                    :total-rows="rows"
                    :per-page="perPage"
                    aria-controls="rankingCompleto"
                ></b-pagination>
        </main>


        <!-- FOOTER -->
        <Footer />
    </div>
</template>

<script>
import { baseUrl } from '../../../config/global'
import axios from 'axios'
import Header from '../templates/Header'
import Footer from '../templates/Footer'

export default {
    name: 'ranking',
    components: { Header, Footer },
    data: function() {
        return{
            sortBy: 'likes',
            sortDesc: true,
            perPage: 20,
            currentPage: 1,
            projetos: [],
            fields: [
                {key: 'tituloProjeto', label: 'Título', sortable: true},
                {key: 'curso.abreviacao', label: 'Curso', sortable: true},
                {key: 'autores', label: 'Autores', sortable: false},
                {key: 'orientadores', label: 'Orientador', sortable: true, formatter: value => value == null ? 'Sem Orientador' : value.nomeOrientador},
                {key: 'dataAvaliacao', label: 'Ano', sortable: true},
                {key: 'download', label: 'Download'}
            ]
        }
    },
    mounted(){
        axios
        .get(baseUrl + 'projetos/buscar/ranking')
        .then(response => (this.projetos = response.data.data))
        document.title = "BTA - Ranking"
    },
    computed: {
      rows() {
        return this.projetos.length
      }
    },
    filters: {
        formatarAlunos: alunos => {
            if(alunos[1] == null || alunos[1] == undefined)
              return alunos[0].nomeAutor
            if(alunos[2] == null || alunos[2] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor
            if(alunos[3] == null || alunos[3] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor + ', ' + alunos[2].nomeAutor
            if(alunos[4] == null || alunos[4] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor + ', ' + alunos[2].nomeAutor + ', ' + alunos[3].nomeAutor
            if(alunos[5] == null || alunos[5] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor + ', ' + alunos[2].nomeAutor + ', ' + alunos[3].nomeAutor + ', ' + alunos[4].nomeAutor
        },
        formatarAno: ano =>{
          return ano.substr(12, 4);
        }
    }
}
</script>

