<template>
  <div class="admin-page" :class="{'hide-menu': !isMenuVisible}">
    <Header title="Biblioteca de Trabalhos Acadêmicos" :hideToggle="false"/>
    <Menu />
    <div id="cursoAdd-content">
      <PageTitle icon="fa fa-home" main="Login" sub="Top"/>
      <b-form>
        <b-row>
          <b-col md="6" sm="12">
              <b-form-group label="Nome do Curso:" label-for="curso-name">
                  <b-form-input id="curso-nome" type="text" v-model="curso.nome" placeholder="Digite o Nome do Curso" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
          <b-col md="6" sm="12">
              <b-form-group label="Abreviação do Curso:" label-for="curso-sigla">
                  <b-form-input id="curso-sigla" type="text" v-model="curso.sigla" placeholder="Digite a Abreviação do Curso" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
        </b-row>
        <b-button variant="primary" @click='save'>
          Salvar
        </b-button>
        <b-button class="ml-2" @click='reset'>
          Cancelar
        </b-button>
      </b-form>
    </div>
    <Footer />
  </div>
</template>

<script>
import { baseUrl, showError } from '../../../config/global'
import { mapState } from 'vuex'
import axios from 'axios'
import PageTitle from '../templates/PageTitle'
import Header from '../templates/Header'
import Menu from '../templates/Menu'
import Footer from '../templates/Footer'

export default {
    name: 'UsuarioList',
    components: { PageTitle, Header, Menu, Footer },
    computed: mapState(['isMenuVisible']),
    data: function(){
      return{
        curso:{
          nome: '',
          sigla: ''
        }
      }
    },
    methods:{
      reset(){
        this.curso = {}
      },
      save(){
        let d = new FormData()
        d.append('username', this.curso.nome)
        d.append('password', this.curso.sigla)
        axios.post(baseUrl + 'usuarios/login', d)
          .then((response) => {
              alert(response.data.message + ' ' + response.data.status)
            if(response.data.status == 'negado'){
              showError()
              return
            }
            this.$toasted.global.defaultSuccess()
          })
          .catch(function(erro){
            alert(erro)
          })
      }
    },
    mounted(){
      document.title = "BTA - Adicionar Curso"
    }
}
</script>

<style>
  #cursoAdd-content{
    grid-area: contentAdmin;
    background-color: #efefef;
    padding: 20px;
  }
</style>