<template>
    <div class="page">
        <!-- HEADER -->
        <Header />

        <main class="container main">
            <h4 class="titulo">Título do Projeto</h4>
            <h6 class="titulo">SubTítulo do Projeto</h6>
        </main>

        <!-- FOOTER -->
        <Footer />
    </div>
</template>

<script>
import { baseUrl, showError } from '../../../config/global'
import axios from 'axios'
import Header from '../templates/Header'
import Footer from '../templates/Footer'

export default {
    name: 'homePage',
    components: { Header, Footer },
    data: function(){
      return{
        windowWidth: 0,
        windowHeigth: 0,
        projeto:{
          tituloProjeto: '',
          subTitulo: '',
          aluno: [],
          ra: [],
          curso: '',
          orientador: '',
          palavras: [],
          resumo: '',
          file: null
        },
        orientadores: ['Silvia Farani', 'Magali Rossi', 'Andreia Machion'],
        cursos: ['Análise e Desenvolvimento de Sistemas', 'Logística', 'Secretariado'],
        contAluno: 1,
        contPalavras: 1
      }
    },
    methods:{
      removerCont(x){
        if(this.contAluno > 1 && x == 1)
          return this.contAluno--
        if(this.contPalavras > 1 && x == 2)
          return this.contPalavras--
      },
      adicionarCont(x){
        if(this.contAluno != 5 && x == 1)
          return this.contAluno++
        if(this.contPalavras != 5 && x == 2)
          return this.contPalavras++
      },
      reset(){
        this.projeto = {}
      },
      save(){
        axios.post(`${baseUrl}`)
          .then(() => {
            this.$toasted.global.defaultSuccess()
          })
          .catch(showError())
      },
    },
    mounted(){
      document.title = "BTA - Adicionar Projeto"
    }
}
</script>

<style>
.titulo{
    text-align: center;
}

</style>