<template>
  <div class="admin-page">
    <Header title="Biblioteca de Trabalhos Acadêmicos" :hideToggle="false"/>
    <Menu />
    <div id="orientadorAdd-content">
      <PageTitle icon="fa fa-home" main="Orientador" sub="Cadastro"/>
      <b-form>
        <b-row>
          <b-col md="6" sm="12">
              <b-form-group label="Nome:" label-for="orientador-name">
                  <b-form-input id="orientador-name" type="text" v-model="orientador.name" placeholder="Digite o Nome do Orientador" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
          <b-col md="6" sm="12">
              <b-form-group label="Código do Orientador:" label-for="orientador-email">
                  <b-form-input id="orientador-email" type="text" v-model="orientador.email" placeholder="Digite o Código de Matricula do Orientador" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
        </b-row>
        <b-button variant="primary" @click='save'>
          Salvar
        </b-button>
        <b-button class="ml-2" @click='reset'>
          Cancelar
        </b-button>
      </b-form>
    </div>
    <Footer />
  </div>
</template>

<script>
import { baseUrl, showError } from '../../../config/global'
import { mapState } from 'vuex'
import axios from 'axios'
import PageTitle from '../templates/PageTitle'
import Header from '../templates/Header'
import Menu from '../templates/Menu'
import Footer from '../templates/Footer'

export default {
    name: 'UsuarioList',
    components: { PageTitle, Header, Menu, Footer },
    computed: mapState(['isMenuVisible']),
    data: function(){
      return{
        orientador:{
          id: '',
          name: '',
          codigo: ''
        }
      }
    },
    methods:{
      reset(){
        this.orientador = {}
      },
      save(){
        axios.post(`${baseUrl}`)
          .then(() => {
            this.$toasted.global.defaultSuccess()
          })
          .catch(showError())
      }
    },
    mounted(){
      document.title = "BTA - Adicionar Orientador"
    }
}
</script>

<style>
  #orientadorAdd-content{
    grid-area: contentAdmin;
    background-color: #efefef;
    padding: 20px;
  }
</style>