<template>
    <header class="headerAdmin">
        <a class="toggle" @click="toggleMenu" v-if="!hideToggle">
            <i class="fa fa-lg" :class="icon"></i>
        </a>
        <h1 class="title">
            <router-link to="/">
                {{ title }}
            </router-link>
        </h1>
        <UserDropdown />
    </header>
</template>

<script>
import UserDropdown from './UserDropdown'

export default {
    name: 'headerAdmin',
    components: { UserDropdown },
    props: {
        title: String,
        hideToggle: Boolean,
        hideUserDropdown: Boolean
    },
    computed: {
        icon(){
            return this.$store.state.isMenuVisible ? 'fa-angle-left' : 'fa-angle-down'
        }
    },
    methods:{
        toggleMenu() {
            this.$store.commit('toggleMenu')
        }
    }
}
</script>

<style>
    .headerAdmin{
        grid-area: headerAdmin;
        background-color: #B3605D;

        display: flex;
        justify-content: center;
        align-items: center;
    }

    .title{
        font-size: 1.3rem;
        color: #fff;
        font-weight: 100;
        flex-grow: 1;
        text-align: center;
        padding-top: 7px;
    }

    .title a{
        color: #fff;
        text-decoration: none;
    }

    .title a:hover{
        color: #fff;
        text-decoration: none;
    }

    header.headerAdmin > a.toggle{
        width: 60px;
        height: 100%;
        color: #fff;
        justify-self: flex-start;
        text-decoration: none;

        display: flex;
        justify-content: center;
        align-items: center;
    }

    header.headerAdmin > a.toggle:hover{
        background-color: rgba(0, 0, 0, 0.2);
    }
</style>