<template>
    <div class="page">
        <!-- HEADER -->
        <Header />
        
        <main class="main">
            <!-- CARROUSEL -->
            <div id="carrousel">
            <b-carousel
            id="carousel-1"
            :interval="4000"
            controls
            indicators
            background="#ababab"
            img-width="1024"
            img-height="400"
            style="text-shadow: 1px 1px 2px #333;"
            >
                <!-- Text slides with image -->
                <b-carousel-slide
                caption="Primeiro Título"
                text="Primeiro SubTítulo"
                img-src="https://picsum.photos/id/1068/1024/400"
                ></b-carousel-slide>
                <!-- Text slides with image -->
                <b-carousel-slide
                caption="Segundo Título"
                text="Segundo SubTítulo"
                img-src="https://picsum.photos/id/1000/1024/400"
                ></b-carousel-slide>
                <!-- Text slides with image -->
                <b-carousel-slide
                caption="Terceiro Título"
                text="Terceiro SubTítulo"
                img-src="https://picsum.photos/id/1050/1024/400"
                ></b-carousel-slide>
            </b-carousel>
            </div>


            <!-- SOBRE -->
            <article class="container">
                <h3>Sobre</h3>
                <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Ut varius dui eget turpis finibus luctus. Curabitur ut ullamcorper massa, in viverra dui. Ut placerat, nisi at consectetur ullamcorper, lorem ipsum gravida mi, sit amet feugiat lacus nisi in lacus. Nulla faucibus nunc lorem, non egestas dui finibus sed. Morbi maximus suscipit nunc, sed aliquet justo sollicitudin tristique.</p>
            </article>

            <!-- BUSCA -->
            <article class="container w-75">
                <div>
                    <h3>Busca</h3>
                    <div class="active-pink-4 mb-4">
                        <input class="form-control" type="text" placeholder="Pesquisar" aria-label="Search">
                    </div>
                    <div id="grupoBotaoBusca">
                        <router-link to="/busca" class="botoesBusca">
                            <b-button variant="outline-danger">Busca</b-button>
                        </router-link>
                        <router-link to="/busca" class="botoesBusca">
                            <b-button variant="outline-danger">Busca Avançada</b-button>
                        </router-link>
                    </div>
                </div>
            </article>

            <!-- RANKING -->
            <article class="container">
                <h3>Ranking</h3>
                    <b-table 
                        class="table-rank"
                        striped hover 
                        :items="info" 
                        :fields="fields"
                        :sort-by.sync="sortBy"
                        :sort-desc.sync="sortDesc"
                    >
                        <template slot="tituloProjeto" slot-scope="titulo">
                            <a href="#" target="_blank">{{ titulo.item.tituloProjeto }} </a>
                        </template>
                        <template slot="alunos" slot-scope="aluno">
                            {{ aluno.item.alunos|formatarAlunos }}
                        </template>
                        <template slot="download">
                            <b-button variante="primary" class="ml-3">
                                <a class="download" href="#" download="#"><i class="fa fa-download"></i></a>
                            </b-button>
                        </template>
                    </b-table>
                <div class="botaoCentro">
                    <router-link to="/ranking">
                        <b-button variant="outline-danger">Ranking Completo</b-button>
                    </router-link>
                </div>
            </article>
        </main>
        <Footer />
    </div>
</template>

<script>
import axios from 'axios'
import Header from '../templates/Header'
import Footer from '../templates/Footer'

export default {
    name: 'homePage',
    components: { Header, Footer },
    data: function() {
        return {
            baseClass: 'v-icon',
            sortBy: 'likes',
            sortDesc: true,
            fields: [
                {key: 'tituloProjeto', label: 'Título'}, 
                {key: 'alunos', label: 'Aluno'},  
                {key: 'nomeOrientador', label: 'Orientador', sortable: false}, 
                {key: 'curso', label: 'Curso', sortable: false}, 
                {key: 'likes', label: 'Likes', sortable: false}, 
                {key: 'download', label: 'Download'}
            ],
            info: {}
        }
    },
    mounted(){
        axios
        .get('https://api.myjson.com/bins/1gu35y')
        .then(response => (this.info = response.data))
        document.title = "BTA - Index"
    },
    filters: {
        formatarAlunos: alunos => {
            if(alunos[1] == null || alunos[1] == undefined)
                return alunos[0]
            if(alunos[2] == null || alunos[2] == undefined)
                return alunos[0] + ', ' + alunos[1]
            if(alunos[3] == null || alunos[3] == undefined)
                return alunos[0] + ', ' + alunos[1] + ', ' + alunos[2]
            if(alunos[4] == null || alunos[4] == undefined)
                return alunos[0] + ', ' + alunos[1] + ', ' + alunos[2] + ', ' + alunos[3]
            if(alunos[5] == null || alunos[5] == undefined)
                return alunos[0] + ', ' + alunos[1] + ', ' + alunos[2] + ', ' + alunos[3] + ', ' + alunos[4]
        }
    }
}

</script>

<style>
.itemMenu{
    color: black;
}

.itemMenu:hover{
    text-decoration: none;
}

article{
    margin: 10px 0;
}

article h3{
    text-align: center;
    padding: 10px;
}

#grupoBotaoBusca{
    display: flex;
    justify-content: center;
}

.botoesBusca + .botoesBusca{
    margin-left: 10px;
}


.botoesBusca a{
    margin-top: 15px;
    background-color: #0066FF;
    border: none;
    color: white;
    padding: 10px 20px;
    text-align: center;
    text-decoration: none;
    display: inline-block;
    cursor: pointer;
}

.itemFooter{
    padding: 10px 0px;
}
</style>