<template>
  <div class="admin-page">
    <Header title="Biblioteca de Trabalhos Acadêmicos" :hideToggle="false"/>
    <Menu />
    <div id="cursoList-content">
      <PageTitle icon="fa fa-home" main="Curso" sub="Listagem"/>
      <b-table hover striped :items="cursos" :fields="fields">
        <template slot="actions" slot-scope="row">
          <b-button variante="primary" class="mr-2">
            <i class="fa fa-pencil"></i>
          </b-button>
          <b-button v-b-modal.modal-center @click="modal(row.item)">
            <i class="fa fa-trash"></i>
          </b-button>
        </template>
      </b-table>

    <div v-if="showModalEdit">
      <transition name="modal">
        <div class="modal-mask">
          <div class="modal-wrapper">
            <div class="modal-dialog" role="document">
              <div class="modal-content">
                <div class="modal-header">
                  <h5 class="modal-title">Excluir</h5>
                  <button type="button" class="close" data-dismiss="modal" aria-label="Close">
                    <span aria-hidden="true" @click="showModalEdit = false">&times;</span>
                  </button>
                </div>
                <div class="modal-body">
                  <p>Deseja excluir o curso {{ cursoEscolhido }} ?</p>
                </div>
                <div class="modal-footer">
                  <button type="button" class="btn btn-primary" @click="showModalEdit = false">Cancelar</button>
                  <button type="button" class="btn btn-danger" @click="excluir" >Excluir</button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </transition>
    </div>

    </div>
    <Footer />
  </div>
</template>

<script>
import { showError, baseUrl } from '../../../config/global'
import { mapState } from 'vuex'
import axios from 'axios'
import PageTitle from '../templates/PageTitle'
import Header from '../templates/Header'
import Menu from '../templates/Menu'
import Footer from '../templates/Footer'

export default {
    name: 'UsuarioList',
    components: { PageTitle, Header, Menu, Footer },
    computed: mapState(['isMenuVisible']),
    data: function(){
      return{
        showModalEdit: false,
        cursoEscolhido: '',
        cursos: [],
        fields: [
          {key: 'codCurso', label: 'Código', sortable: false},
          {key: 'abreviacao', label: 'Abreviação', sortable: true},
          {key: 'descricaoCurso', label: 'Nome', sortable: false},
          {key: 'ativo', label: 'Ativo', sortable: true, formatter: value => value == 1 ? 'Sim' : 'Não'},
          {key: 'actions', label: 'Ações'}
        ]
      }
    },
    mounted(){
        axios.get(baseUrl + "cursos/buscar")
          .then(response => (this.cursos = response.data.data))
          .catch(showError)
        
        document.title = "BTA - Lista de Cursos"
    },
    methods: {
      excluir(){
        alert('Deletado')
      },
      modal(item){
        this.cursoEscolhido = item.descricaoCurso
        this.showModalEdit = true
      }
    }
}
</script>

<style>
  #cursoList-content{
    grid-area: contentAdmin;
    background-color: #efefef;
    padding: 20px;
  }
</style>