//Rotas
import Vue from 'vue'
import VueRouter from 'vue-router'

//Pages
import Index from '../components/home/pages/Index'
import Sobre from '../components/home/pages/Sobre'
import Busca from '../components/home/pages/Busca'
import Ranking from '../components/home/pages/Ranking'
import Contato from '../components/home/pages/Contato'
import Erro404 from '../components/home/pages/Erro'
import Projeto from '../components/home/pages/Projeto'
import Login from '../components/admin/pages/Login'

//Admin
import IndexAdmin from '../components/admin/pages/Index'
import ProjetoList from '../components/admin/pages/ProjetoList'
import ProjetoAdd from '../components/admin/pages/ProjetoAdd'
import OrientadorList from '../components/admin/pages/OrientadorList'
import OrientadorAdd from '../components/admin/pages/OrientadorAdd'
import UsuarioList from '../components/admin/pages/UsuarioList'
import UsuarioAdd from '../components/admin/pages/UsuarioAdd'
import CursoList from '../components/admin/pages/CursoList'
import CursoAdd from '../components/admin/pages/CursoAdd'

Vue.use(VueRouter)

const routes = [{
    name: 'Index',
    path: '/',
    component: Index
},{
    name: 'Sobre',
    path: '/sobre',
    component: Sobre
},{
    name: 'Busca',
    path: '/busca',
    component: Busca
},{
    name: 'Ranking',
    path: '/ranking',
    component: Ranking
},{
    name: 'Contato',
    path: '/contato',
    component: Contato
},{
    name: 'Projeto',
    path: '/projeto',
    component: Projeto
},{
    name: 'Login',
    path: '/login',
    component: Login
},{
    name: 'IndexAdmin',
    path: '/admin',
    component: IndexAdmin
},{
    name: 'ProjetoList',
    path: '/admin/projetos',
    component: ProjetoList
},{
    name: 'ProjetoAdd',
    path: '/admin/projetos/adicionar',
    component: ProjetoAdd
},{
    name: 'listaOrientador',
    path: '/admin/orientador',
    component: OrientadorList
},{
    name: 'OrientadorAdd',
    path: '/admin/orientador/adicionar',
    component: OrientadorAdd
},{
    name: 'UsuarioList',
    path: '/admin/usuario',
    component: UsuarioList
},{
    name: 'UsuarioAdd',
    path: '/admin/usuario/adicionar',
    component: UsuarioAdd
},{
    name: 'CursoList',
    path: '/admin/curso',
    component: CursoList
},{
    name: 'CursoAdd',
    path: '/admin/curso/adicionar',
    component: CursoAdd
},{
    name: 'IndexAdmin',
    path: '/admin/*',
    component: IndexAdmin
},{
    name: 'Erro404',
    path: '/*',
    component: Erro404
}]

const router = new VueRouter({
    mode: 'history',
    routes: routes
})

export default router