<template>
  <div class="admin-page">
    <Header title="Biblioteca de Trabalhos Acadêmicos" :hideToggle="false"/>
    <Menu />
    <div id="usuarioAdd-content">
      <PageTitle icon="fa fa-home" main="Usuário" sub="Cadastro"/>
      <b-form>
        <input id="user-id" type="hidden" v-model="user.id">
        <b-row>
          <b-col md="6" sm="12">
              <b-form-group label="Nome:" label-for="user-name">
                  <b-form-input id="user-name" type="text" v-model="user.name" placeholder="Digite o Nome do Usuário" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
          <b-col md="6" sm="12">
              <b-form-group label="E-mail:" label-for="user-email">
                  <b-form-input id="user-email" type="text" v-model="user.email" placeholder="Digite o E-mail do Usuário" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
        </b-row>
        <b-row class="mt-3 mb-3">
          <b-col md="3" sm="6">
            <b-form-checkbox id="user-admin" v-model="user.admin">
              Administrador
            </b-form-checkbox>
          </b-col>
          <b-col md="3" sm="6">
            <b-form-checkbox id="user-coordenador" v-model="user.coordenador">
              Coordenador
            </b-form-checkbox>
          </b-col>
          <b-col md="3" sm="6">
            <b-form-checkbox id="user-orientador" v-model="user.orientador">
              Orientador
            </b-form-checkbox>
          </b-col>
          <b-col md="3" sm="6">
            <b-form-checkbox id="user-secretaria" v-model="user.secretaria">
              Secretaria
            </b-form-checkbox>
          </b-col>
        </b-row>
        <b-row>
          <b-col md="6" sm="12">
              <b-form-group label="Senha:" label-for="user-password">
                  <b-form-input id="user-password" type="password" v-model="user.password" placeholder="Digite a Senha do Usuário" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
          <b-col md="6" sm="12">
              <b-form-group label="Conrimação de Senha:" label-for="user-confirm-password">
                  <b-form-input id="user-confirm-password" type="password" v-model="user.confirmPassword" placeholder="Confirme a Senha do Usuário" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
        </b-row>
        <b-button variant="primary" @click='save'>
          Salvar
        </b-button>
        <b-button class="ml-2" @click='reset'>
          Cancelar
        </b-button>
      </b-form>
    </div>
    <Footer />
  </div>
</template>

<script>
import { baseUrl, showError } from '../../../config/global'
import { mapState } from 'vuex'
import axios from 'axios'
import PageTitle from '../templates/PageTitle'
import Header from '../templates/Header'
import Menu from '../templates/Menu'
import Footer from '../templates/Footer'

export default {
    name: 'UsuarioList',
    components: { PageTitle, Header, Menu, Footer },
    computed: mapState(['isMenuVisible']),
    data: function(){
      return{
        user:{
          id: '',
          name: '',
          email: '',
          password: '',
          confirmPassword: '',
          admin: '',
          coordenador: '',
          orientador: '',
          secretaria: ''
        }
      }
    },
    methods:{
      reset(){
        this.user = {}
      },
      save(){
        axios.post(`${baseUrl}`)
          .then(() => {
            this.$toasted.global.defaultSuccess()
          })
          .catch(showError())
      }
    },
    mounted(){
      document.title = "BTA - Adicionar Usuário"
    }
}
</script>

<style>
  #usuarioAdd-content{
    grid-area: contentAdmin;
    background-color: #efefef;
    padding: 20px;
  }
</style>